import {ITEMS,learned,display} from './engine.js';
import {STATS,SLOTS,ITEM_DESCRIPTIONS,itemBonuses,equipmentPreview} from './equipment-model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pic=(path,alt='',cls='')=>`<img src="assets/${esc(path)}" alt="${esc(alt)}" class="${cls}">`;
const act=(label,action,args='',cls='',disabled=false)=>`<button data-action="${action}" data-args="${esc(args)}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`;
const named=(data,kind,id)=>data.catalog[kind].find(x=>x.id===id)?.name||id;
export function inspectedPerson(g,ui){const p=g.s.party.find(p=>p.id===ui.personId)||g.s.party[0];ui.personId=p.id;return p;}
function itemIcon(data,slot,id){if(id&&ITEMS[id])return 'equipment/'+id+'.svg';return data.assets.icons[{武器:'weapon',防具:'armor',配件:'accessory'}[slot]||'chest'];}
export function peoplePicker(g,data,selected,action='inspectPerson',label='選擇角色',eligible=()=>true){return `<div class="picker-label">${label}<span>${g.s.party.length>2?'左右滑動選擇':''}</span></div><div class="people-picker" role="group" aria-label="${label}">${g.s.party.map(p=>`<button class="person-choice ${selected===p.id?'selected':''}" data-action="${action}" data-args="${p.id}" aria-pressed="${selected===p.id}" ${eligible(p)?'':'disabled'}>${pic(data.assets.portraits[p.race],'')}<span><b>${esc(display(p))}</b><small>${named(data,'professions',p.profession)} · ${p.hp<=0?'已倒下':p.asleep?'睡眠中':'Lv.'+p.level}</small><small>HP ${p.hp}/${p.maxHp} · 體力 ${p.st}/${p.maxSt}</small></span><i>${selected===p.id?'✓':''}</i></button>`).join('')}</div>`;}
export function statStrip(g,p){return `<div class="character-stats">${STATS.map(([k,n])=>`<div><small>${n}</small><strong>${g.stat(p,k)}</strong></div>`).join('')}</div>`;}
function loadout(data,p,compact=false){return `<div class="loadout ${compact?'compact':''}">${SLOTS.map(slot=>{const id=p.gear[slot],it=ITEMS[id];return act(`${pic(itemIcon(data,slot,id),'')}<span><small>${slot}</small><strong>${it?.name||'未裝備'}</strong><em>${itemBonuses(id)}</em></span><b class="chevron">›</b>`,'gearSlot',slot,'loadout-slot');}).join('')}</div>`;}
export function characterPanel(g,data,ui){const p=inspectedPerson(g,ui),flaw=data.traits.flaws.find(f=>f.id===p.flaw),available=['ready','event'].includes(g.s.mode);
 return peoplePicker(g,data,p.id)+`<div class="character-profile"><div class="character-art">${pic(data.assets.characters[p.race+'_'+p.profession],display(p))}<span>LV. ${p.level} / 18</span></div><div><h3>${esc(display(p))}</h3><p>${named(data,'races',p.race)} · ${named(data,'professions',p.profession)}</p>${[['HP',p.hp,p.maxHp,'hp'],['體力',p.st,p.maxSt,'st'],['ESP',p.esp,p.maxEsp,'esp']].map(([name,v,max,type])=>`<div class="vital"><span>${name}</span><b>${v}<small> / ${max}</small></b><div class="bar ${type}"><i style="width:${v/max*100}%"></i></div></div>`).join('')}</div></div>`+statStrip(g,p)+`<div class="section-label">目前裝備<span>點選部位，查看替換裝備</span></div>`+loadout(data,p)+`${p.aspirations?.shared?`<section class="character-hope"><h4>關於樂園</h4><p>${esc(p.aspirations.raceWish)}</p><p>${esc(p.aspirations.professionWish)}</p><small>旅途中，他曾向你說起這樣的日子。</small></section>`:''}<details class="character-details"><summary>特性與超能力 <span>＋</span></summary>${['race_'+p.race,'profession_'+p.profession].map(id=>{const t=data.traits.advantages.find(t=>t.id===id);return `<div class="trait-detail"><b>＋ ${t.name}</b><p>${esc(t.effect)}</p></div>`;}).join('')}<div class="trait-detail bad"><b>− ${flaw?.name||'未知缺點'}</b><p>${esc(flaw?.effect)}</p></div><div class="power-list">${learned(p).map(pow=>`<span>✧ ${pow.name}<small>${pow.cost} ESP</small></span>`).join('')}</div></details><div class="character-actions">${act(p.id===g.s.driver?'目前駕駛':'接手駕駛','driver',p.id,'',!available||p.st<=0||p.hp<=0||p.id===g.s.driver)}${act('使用藥品 · '+g.s.resources.medicine,'heal',p.id,'',!available||g.s.resources.medicine<1||p.hp>=p.maxHp||p.hp<=0)}</div><details class="separation"><summary>管理同行關係</summary><p>離開的同伴會帶走身上的裝備。</p>${act('遣散這位同伴','dismissAsk',p.id,'danger',!available||g.s.party.length<=1||p.hp<=0||p.id===g.s.protagonistId)}</details>`;
}
export function comparisonCard(g,data,ui,id,{shop=false}={}){const p=inspectedPerson(g,ui),preview=equipmentPreview(g,p,id);if(!preview)return '';const {item,previous,stats,notes,same,owned}=preview,allowed=['ready','event'].includes(g.s.mode)&&p.hp>0;
 return `<section class="equipment-comparison" aria-label="裝備比較" id="equipment-comparison"><div class="section-label">${esc(display(p))}<span>${item.slot}比較</span></div><div class="comparison-items"><div><small>目前裝備</small>${pic(itemIcon(data,item.slot,previous),'')}<strong>${ITEMS[previous]?.name||'未裝備'}</strong><em>${itemBonuses(previous)}</em></div><span class="compare-arrow">→</span><div class="new-item"><small>${shop?'商店裝備':'準備換上'}</small>${pic(itemIcon(data,item.slot,id),'')}<strong>${item.name}</strong><em>${itemBonuses(id)}</em></div></div><table class="comparison-table"><caption>角色總屬性變化</caption><thead><tr><th>屬性</th><th>目前</th><th>換裝後</th><th>變化</th></tr></thead><tbody>${stats.map(v=>`<tr class="${v.delta>0?'gain':v.delta<0?'loss':'unchanged'}"><th>${v.name}</th><td>${v.before}</td><td>→ <b>${v.after}</b></td><td>${v.delta>0?'＋'+v.delta:v.delta<0?'−'+Math.abs(v.delta):'—'}</td></tr>`).join('')}</tbody></table><p class="item-description">${ITEM_DESCRIPTIONS[id]}</p>${notes.map(n=>`<p class="equipment-note">${n}</p>`).join('')}${shop?`<p class="return-note">購買後放入公共背包，再選擇角色裝備。</p>${act('購買 '+item.name+' · '+g.price(item.price)+' 廢料','buy','item:'+id,'primary equip-confirm',g.s.resources.scrap<g.price(item.price))}`:`<p class="return-note">${!allowed?(p.hp<=0?'角色已倒下，目前只能查看裝備。':'行車或戰鬥中只能查看；停靠後可換裝。'):same?'這位角色已穿戴相同裝備。':previous?`${ITEMS[previous].name}會放回公共背包。`:'裝備到目前空出的部位。'}</p>${act(same?'已穿戴相同裝備':'換上 '+item.name,'confirmEquip',id,'primary equip-confirm',!allowed||!owned||same)}`}</section>`;
}
export function inventoryPanel(g,data,ui){const p=inspectedPerson(g,ui),counts=new Map();g.s.inventory.forEach(id=>counts.set(id,(counts.get(id)||0)+1));const candidates=[...counts].filter(([id])=>ITEMS[id]&&(ui.slot==='全部'||ITEMS[id].slot===ui.slot));if(ui.itemId&&!g.s.inventory.includes(ui.itemId))ui.itemId=null;
 return peoplePicker(g,data,p.id)+statStrip(g,p)+`<div class="section-label">目前穿戴<span>公共背包不限容量</span></div>`+loadout(data,p,true)+`<div class="bag-resources"><span>藥品 <b>${g.s.resources.medicine}</b></span><span>廢料 <b>${g.s.resources.scrap}</b></span><span>背包裝備 <b>${g.s.inventory.length}</b></span></div><div class="equipment-tabs" role="group" aria-label="裝備分類">${['全部',...SLOTS].map(slot=>`<button data-action="gearFilter" data-args="${slot}" class="${ui.slot===slot?'selected':''}" aria-pressed="${ui.slot===slot}">${slot}</button>`).join('')}</div><div class="inventory-grid">${candidates.map(([id,count])=>{const it=ITEMS[id];return `<button data-action="inspectItem" data-args="${id}" class="inventory-item ${id===ui.itemId?'selected':''}" aria-pressed="${id===ui.itemId}">${pic(itemIcon(data,it.slot,id),'')}<strong>${it.name}</strong><small>${itemBonuses(id)}</small><span>${p.gear[it.slot]===id?'已穿戴同款':'點選比較'}${count>1?' · ×'+count:''}</span></button>`;}).join('')||`<div class="empty-equipment">${ui.slot==='全部'?'背包暫時沒有備用裝備。':'背包沒有備用'+ui.slot+'。'}<small>目前穿戴的裝備仍顯示在上方。</small></div>`}</div>${ui.itemId?comparisonCard(g,data,ui,ui.itemId):candidates.length?'<p class="comparison-hint">點選裝備，先查看屬性差異，再決定是否更換。</p>':''}<div class="bag-footer">${act('匯出旅程存檔','export','','quiet')}</div>`;
}
export function watchPanel(g,data,ui){if(!g.alive().some(p=>p.id===ui.watchId&&p.st>0))ui.watchId=null;return `<div class="rest-summary"><strong>休息 4 小時</strong><span>睡眠恢復體力與 ESP</span></div><p class="panel-explanation">選擇守夜者。他會消耗 4 體力，其餘隊員入睡。</p><div class="watch-grid" role="group" aria-label="守夜安排"><button data-action="watch" data-args="" class="watch-none ${!ui.watchId?'selected':''}" aria-pressed="${!ui.watchId}"><b>全員睡眠 · 無人守夜</b><small>若被襲擊，敵人先攻；只有被打中的角色會醒來。</small></button>${g.s.party.map(p=>`<button data-action="watch" data-args="${p.id}" class="watch-choice ${ui.watchId===p.id?'selected':''}" ${p.hp<=0||p.st<=0?'disabled':''} aria-pressed="${ui.watchId===p.id}">${pic(data.assets.portraits[p.race],'')}<b>${esc(display(p))}</b><small>體力 ${p.st}/${p.maxSt}</small><em>${p.hp<=0?'無法守夜':p.st<=0?'體力耗盡':ui.watchId===p.id?'守夜後 '+Math.max(0,p.st-4):'點選守夜'}</em></button>`).join('')}</div><p class="rest-outcome">${ui.watchId?'已安排守夜：'+esc(display(g.s.party.find(p=>p.id===ui.watchId)))+'。':'目前安排全員入睡。'}<br>睡眠通常恢復 16 體力；角色缺點可能影響恢復量。</p>${act('確認安排 · 休息 4 小時','sleep','','primary rest-confirm')}`;}
export function creationChoices(data,race,job){return `<div class="creation-choices">${act(`${pic(data.assets.portraits[race],'')}<span><small>選擇種族</small><b>${named(data,'races',race)}</b></span><i>›</i>`,'openPicker','race','creation-choice')}${act(`${pic(data.assets.characters[race+'_'+job],'')}<span><small>選擇職業</small><b>${named(data,'professions',job)}</b></span><i>›</i>`,'openPicker','job','creation-choice')}</div>`;}
export function choiceDialog(data,kind,race,job){if(!kind)return '';const races=kind==='race',items=data.catalog[races?'races':'professions'],selected=races?race:job;return `<div class="panel-back choice-back" data-panel="picker-${kind}"><section class="panel choice-panel" role="dialog" aria-modal="true" aria-labelledby="choice-title"><div class="panel-header"><div><small>CREATE YOUR TRAVELLER</small><h2 id="choice-title" tabindex="-1">${races?'選擇種族':'選擇職業'}</h2></div>${act('關閉','closePicker','','quiet')}</div><p class="panel-explanation">${races?'每個種族都有獨有特性與超能力。':'職業帶來專長與事件選項，不限制超能力。'}</p><div class="creation-grid">${items.map(it=>`<button data-action="pick${races?'Race':'Job'}" data-args="${it.id}" class="creation-option ${it.id===selected?'selected':''}" aria-pressed="${it.id===selected}">${pic(races?data.assets.characters[it.id+'_'+job]:data.assets.characters[race+'_'+it.id],'')}<strong>${it.name}</strong><small>${esc(it.specialty)}</small><i>${it.id===selected?'✓':''}</i></button>`).join('')}</div></section></div>`;}
